mapper.select:
SELECT BC.id, BC.name, BC.manufacturer_code as manufacturerCode, BC.address, CONCAT(BC.area_code,BC.street_code) as areaStreet, BC.contact as contact, BC.contact_mobile as contactMobile, BC.stove_number as stoveNumber, BP.conn_date as connDate, BP.port_name as portName, BP.name as pointName, BP.point_mac as pointMac, BP.status as status, BP.air_volume as airVolume, BP.tech_roadmap as techRoadmap, BPP.second_voltage as secondVoltage, BPP.second_current as secondCurrent, BLD.lampblack_data as lampblackData, BLD.matter_data as matterData, BLD.nmhc_data as nmhcData, BLD.purifier_status as purifierStatus, BLD.purifier_voltage_diff as purifierVoltageDiff, BLD.fan_status as fanStatus, BLD.fan_current as fanCurrent, date_format(BLD.create_time,'%Y-%m-%d %H:%i:%S') as createTime FROM base_company BC LEFT JOIN base_point BP ON BP.company_id = BC.id LEFT JOIN ${tableLampblack} BLD ON BLD.point_mac = BP.point_mac LEFT JOIN ${tablePurifier} BPP ON BPP.bu_lampblack_id = BLD.id where 1=1
AND BC.id = #{companyid,jdbcType=VARCHAR}
AND BP.point_mac = #{pointid,jdbcType=VARCHAR}
AND date_format(BLD.create_time,'%Y-%m-%d %H:%i:%S') > #{startTime}
AND date_format(BLD.create_time,'%Y-%m-%d %H:%i:%S') < #{endTime}
AND BC.fid_region = #{fidRegion}
order by BLD.create_time desc

SELECT BC.id, BC.name, BC.manufacturer_code as manufacturerCode, BC.address, CONCAT(BC.area_code,BC.street_code) as areaStreet, BC.contact as contact, BC.contact_mobile as contactMobile, BC.stove_number as stoveNumber, BP.conn_date as connDate, BP.port_name as portName, BP.name as pointName, BP.point_mac as pointMac, BP.status as status, BP.air_volume as airVolume, BP.tech_roadmap as techRoadmap, BPP.second_voltage as secondVoltage, BPP.second_current as secondCurrent, BLD.lampblack_data as lampblackData, BLD.matter_data as matterData, BLD.nmhc_data as nmhcData, BLD.purifier_status as purifierStatus, BLD.purifier_voltage_diff as purifierVoltageDiff, BLD.fan_status as fanStatus, BLD.fan_current as fanCurrent, date_format(BLD.create_time,'%Y-%m-%d %H:%i:%S') as createTime FROM base_company BC LEFT JOIN base_point BP ON BP.company_id = BC.id LEFT JOIN ${tableLampblack} BLD ON BLD.point_mac = BP.point_mac LEFT JOIN ${tablePurifier} BPP ON BPP.bu_lampblack_id = BLD.id WHERE BLD.create_time IN (SELECT MAX(BLDS.create_time) FROM ${tableLampblack} BLDS RIGHT JOIN base_point BPS ON BLDS.point_mac = BPS.point_mac RIGHT JOIN base_company BCS ON BPS.company_id = BCS.id where 1=1
AND BLDS.create_time between date_add(now(), interval -1 hour) and now()
AND BLDS.create_time between date_add(now(), interval -2 hour) and date_add(now(), interval -1 hour)
AND BLDS.create_time between date_add(now(), interval -3 hour) and date_add(now(), interval -2 hour)
AND date_format(BLD.create_time,'%Y-%m-%d %H:%i:%S') > #{startTime}
AND date_format(BLD.create_time,'%Y-%m-%d %H:%i:%S') < #{endTime}
group by BLDS.point_mac order by BLDS.create_time desc)
AND BC.id in
#{item}
AND BP.fid_region = #{fidRegion}
AND BP.point_mac = #{pointMac,jdbcType=VARCHAR}
group by BP.point_mac order by BLD.create_time desc

SELECT BC.id, BC.name, BC.manufacturer_code as manufacturerCode, BC.address, CONCAT(BC.area_code,BC.street_code) as areaStreet, BC.contact as contact, BC.contact_mobile as contactMobile, BC.stove_number as stoveNumber, BP.conn_date as connDate, BP.port_name as portName, BP.name as pointName, BP.point_mac as pointMac, BP.status as status, BP.air_volume as airVolume, BP.tech_roadmap as techRoadmap, BPP.second_voltage as secondVoltage, BPP.second_current as secondCurrent, BLD.lampblack_data as lampblackData, BLD.matter_data as matterData, BLD.nmhc_data as nmhcData, BLD.purifier_status as purifierStatus, BLD.purifier_voltage_diff as purifierVoltageDiff, BLD.fan_status as fanStatus, BLD.fan_current as fanCurrent, date_format(BLD.create_time,'%Y-%m-%d %H:%i:%S') as createTime FROM base_company BC LEFT JOIN base_point BP ON BP.company_id = BC.id LEFT JOIN ${tableLampblack} BLD ON BLD.point_mac = BP.point_mac LEFT JOIN ${tablePurifier} BPP ON BPP.bu_lampblack_id = BLD.id WHERE 1=1
AND BC.id in
#{item}
AND BP.fid_region = #{fidRegion}
AND BP.point_mac = #{pointMac,jdbcType=VARCHAR}
group by BP.point_mac order by BLD.create_time desc

SELECT BC.id, BC.name, date_format(BLD.create_time,'%Y-%m-%d %H:%i:%S') as createTime, BC.manufacturer_code as manufacturerCode, BC.address, CONCAT(BC.area_code,BC.street_code) as areaStreet, BC.contact as contact, BC.contact_mobile as contactMobile, BC.stove_number as stoveNumber, BP.conn_date as connDate, BP.port_name as portName, BP.name as pointName, BP.point_mac as pointMac, BP.status as status, BP.air_volume as airVolume, BP.tech_roadmap as techRoadmap, BPP.second_voltage as secondVoltage, BPP.second_current as secondCurrent, BLD.lampblack_data as lampblackData, BLD.matter_data as matterData, BLD.nmhc_data as nmhcData, BLD.purifier_status as purifierStatus, BLD.purifier_voltage_diff as purifierVoltageDiff, BLD.fan_status as fanStatus, BLD.fan_current as fanCurrent FROM base_company BC LEFT JOIN base_point BP ON BP.company_id = BC.id LEFT JOIN ${tableLampblack} BLD ON BLD.point_mac = BP.point_mac LEFT JOIN ${tablePurifier} BPP ON BPP.bu_lampblack_id = BLD.id WHERE 1=1
AND BP.fid_region = #{fidRegion}
AND BP.point_mac = #{pointMac,jdbcType=VARCHAR} order by BLD.create_time desc

SELECT FLOOR((TIMESTAMPDIFF(SECOND,create_time, #{createTime}) - 1)/1800) AS section, COUNT(1), MAX(lampblack_data) as lampblackDataMax, MAX(matter_data) as matterData, MAX(nmhc_data) as nmhcData, create_time, IFNULL(SUM(lampblack_data > 1 or matter_data > 5 or nmhc_data > 10),0) as a1, IFNULL(SUM(lampblack_data=0 and matter_data=0 and nmhc_data=0),0) as a2 FROM ${tableLampblack} WHERE 1=1
AND date_format(create_time,'%Y-%m-%d') >= DATE_SUB(#{createTime},INTERVAL 1 DAY) AND date_format(create_time,'%Y-%m-%d') < #{createTime}
and point_mac in( SELECT point_mac FROM base_point BP,base_company BC WHERE BP.company_id = BC.id
AND BC.id = #{id,jdbcType=VARCHAR}
AND BP.point_mac = #{pointId,jdbcType=VARCHAR}
) GROUP BY section

select date_format(create_time,'%Y-%m-%d') as mTime
from ${tableLampblack}
WHERE 1=1
    and point_mac in(
        SELECT point_mac FROM base_point BP,base_company BC
        WHERE BP.company_id = BC.id

            AND BC.id = #{id,jdbcType=VARCHAR}


            AND BP.point_mac = #{pointId,jdbcType=VARCHAR}

    )

SELECT BC.name as name,BP.point_mac as mac
FROM base_company BC,base_point BP
WHERE BC.id = BP.company_id
and BC.fid_region = #{fidRegion}

    AND BC.id = #{id,jdbcType=VARCHAR}


    AND BP.point_mac = #{pointId,jdbcType=VARCHAR}
